import java.util.Arrays;
import java.util.Comparator;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<Buku> rak = Arrays.asList(
                new Buku("Belajar Java", 250),
                new Buku("Kamus Saku", 80),
                new Buku("Resep Nusantara", 120));
        String tipis = rak.stream()
                .min(Comparator.comparing(Buku::getHalaman))
                .map(Buku::getJudul)
                .orElse("-");
        System.out.println(tipis);
    }
}

class Buku {
    private String judul;
    private int halaman;

    Buku(String judul, int halaman) {
        this.judul = judul;
        this.halaman = halaman;
    }

    String getJudul() {
        return judul;
    }

    int getHalaman() {
        return halaman;
    }
}

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) {
        List<Pesanan> daftar = Arrays.asList(
                new Pesanan("M1", 30000),
                new Pesanan("M2", 20000),
                new Pesanan("M1", 15000));
        Map<String, Integer> perMeja = daftar.stream()
                .collect(Collectors.groupingBy(Pesanan::getMeja, TreeMap::new,
                        Collectors.summingInt(Pesanan::getTotal)));
        System.out.println(perMeja);
    }
}

class Pesanan {
    private String meja;
    private int total;

    Pesanan(String meja, int total) {
        this.meja = meja;
        this.total = total;
    }

    String getMeja() {
        return meja;
    }

    int getTotal() {
        return total;
    }
}
